inp, outp = sys.argv[1], sys.argv[2]
data = json.load(open(inp, encoding='utf-8'))
docs = {d['doc_id']: d['text'] for d in data['documents']}
conds = {c['condition_id']: c for c in data['study']['conditions']}

def num(s):
    return float(s.replace('×10^', 'e'))

nb = {}   # notebook / transcription records, one per well
raw = {}  # reader automatic export (µM/s), SOP sec 1 says this overrides transcriptions
