    if qid in nb:
        print('DUPLICATE', qid, nb[qid]['src'], src, file=sys.stderr)
    nb[qid] = dict(S=S, v=v, cond=cond, src=src, T=T, note=note)

# D1 Sofia Marchetti, CSV (rate mM/min, S nM)
for line in docs['D1'].splitlines():
    if not line.startswith('QD-'):
        continue
    qid, plate, well, cond, rep, S, rate, t, qc = line.split(',', 8)
    put(qid, num(S) / 1000, num(rate) * 1000 / 60, re.search(r'C\d', cond).group(), 'D1', note=qc.strip())

# D4 Pavel Sokol summary (rate mM/min, S nM); pH 5.5 block relabelled to C4 per D8 chat
cur = None
for line in docs['D4'].splitlines():
    if line.startswith('Condition:'):
        if 'pH 9.0' in line:
            cur = 'C2'
        elif 'MPX-9 at 0.012' in line:
            cur = 'C6'
        elif 'pH 5.5' in line:
            cur = 'C4'
        continue
    m = re.match(r'\s*\[S\] = (\d+): (.*)', line)
    if not m:
        continue
    S = int(m.group(1)) / 1000
    tb = re.search(r'block temp ([\d.]+) °C', line)
    for rm in re.finditer(r'r(\d) ([\d.]+)(?: → re-read ([\d.]+))? \((QD-\d{4})', m.group(2)):
        val = rm.group(3) or rm.group(2)   # re-read replaces first read (SOP sec 3)
        T = float(tb.group(1)) if tb and rm.group(4) in line.split('(')[1] else None
        put(rm.group(4), S, float(val) * 1000 / 60, cur, 'D4', T=T)

# D6 Leila Haddad (slope mAU/min, conc mM, T logged)
cur = None
for line in docs['D6'].splitlines():
    if line.startswith('Plate '):
        if 'Assay: 25C/pH9.0' in line:
            cur = 'C1'
        elif 'Assay: 30C/pH5.5' in line:
            cur = 'C7'
        else:
            cur = None
        continue
    m = re.match(r'^([A-H]\d\d)\s+(QD-\d{4})\s+([\d.]+) mM\s+([\d.]+)\s+([\d.]+)\s*(.*)$', line)
    if m:
        put(m.group(2), float(m.group(3)) * 1000, float(m.group(4)) * 0.2772 / 60, cur, 'D6',
            T=float(m.group(5)), note=m.group(6).strip())

# D7 Nadia Kowalczyk (rate nM/min after her units correction, S µM)
cur = None
for line in docs['D7'].splitlines():
    if line.startswith('### '):
        if '37 °C, pH 7.4' in line:
            cur = 'C3'
        elif 'MPX-9 (12 uM)' in line:
            cur = 'C6'
        elif 'pH 5.5 / 30 °C' in line:
            cur = 'C7'
        elif 'pH 9.0, 25 °C' in line:
            cur = 'C2'
        else:
            cur = None
        continue
    m = re.match(r'^\| (QD-\d{4}) \| (\w\d\d) \| ([\d.]+) \| ([\d.e+\-]+) \|', line)
    if m:
        put(m.group(1), float(m.group(3)), float(m.group(4)) / 1000 / 60, cur, 'D7')

# D11 Yuki Tanabe bench log (rate µM/min, S nM), transcribed by hand
yuki = {
    'QD-0590': (2500, 34.3), 'QD-0591': (5000, 66.2), 'QD-0592': (8000, 99.5), 'QD-0593': (15000, 147),
    'QD-0594': (30000, 193), 'QD-0595': (60000, 247), 'QD-0596': (120000, 274), 'QD-0597': (250000, 295),
    'QD-0598': (500000, 316),
    'QD-0671': (120000, 142), 'QD-0672': (8000, 28.2), 'QD-0673': (250000, 1565), 'QD-0674': (500000, 172),
    'QD-0675': (15000, 50.2), 'QD-0676': (60000, 109), 'QD-0677': (5000, 21.1), 'QD-0678': (2500, 11.6),
    'QD-0679': (30000, 74.5),
    'QD-0494': (2500, 10.2), 'QD-0495': (5000, 21.4), 'QD-0496': (8000, 31.5), 'QD-0497': (15000, 58.9),
    'QD-0498': (30000, 99.8), 'QD-0499': (60000, 148), 'QD-0500': (120000, 217), 'QD-0501': (250000, 262),
    'QD-0502': (500000, 290),
    'QD-0569': (500000, 154), 'QD-0570': (250000, 152), 'QD-0571': (2500, 7.82), 'QD-0572': (120000, 126),
    'QD-0573': (5000, 14.8), 'QD-0574': (8000, 22.8), 'QD-0575': (30000, 73.6), 'QD-0576': (60000, 92.9),
    'QD-0577': (15000, 39.6),
}
cond_of_yuki = {}
for q in ['QD-0590','QD-0591','QD-0592','QD-0593','QD-0594','QD-0595','QD-0596','QD-0597','QD-0598']:
    cond_of_yuki[q] = 'C5'
for q in ['QD-0671','QD-0672','QD-0673','QD-0674','QD-0675','QD-0676','QD-0677','QD-0678','QD-0679']:
    cond_of_yuki[q] = 'C2'
for q in ['QD-0494','QD-0495','QD-0496','QD-0497','QD-0498','QD-0499','QD-0500','QD-0501','QD-0502']:
    cond_of_yuki[q] = 'C4'
for q in ['QD-0569','QD-0570','QD-0571','QD-0572','QD-0573','QD-0574','QD-0575','QD-0576','QD-0577']:
    cond_of_yuki[q] = 'C3'
for q, (S, v) in yuki.items():
    put(q, S / 1000, v / 60, cond_of_yuki[q], 'D11')

# D12 Owen Achterberg export (slope mAU/min, conc nM, T logged)
cur = None
for line in docs['D12'].splitlines():
    if line.startswith('Plate '):
        cur = re.search(r'Assay: .*?(C\d)', line).group(1)
        continue
    m = re.match(r'^([A-H]\d\d)\s+(QD-\d{4})\s+(\S+)\s+nM\s+([\d.]+)\s+([\d.]+)\s*(.*)$', line)
    if m:
        put(m.group(2), num(m.group(3)) / 1000, float(m.group(4)) * 0.2772 / 60, cur, 'D12',
            T=float(m.group(5)), note=m.group(6).strip())

