explicit = {
    'QD-0806': 'bubble throughout read (sec 2.2; Sofia correction)',
    'QD-0711': 'air in well during read (sec 2.2; author confirmed Dara report)',
    'QD-0748': 'enzyme added twice (sec 2.3; Pavel correction)',
    'QD-0607': 'OVR flag (sec 2.1; Nadia addendum)',
    'QD-0636': 'SAT flag (sec 2.1; Owen channel message)',
    'QD-0509': 'spill (sec 2.3; Owen channel message)',
    'QD-0569': 'bubble 2 min after read start (sec 2.2; Yuki log)',
    'QD-0854': 'bubble 6 min after first read cycle, 8 min read (sec 2.2; Leila comment)',
}
setpoint = {k: c['temperature_C'] for k, c in conds.items()}
excluded = {}
for q, r in nb.items():
    if q in explicit:
        excluded[q] = explicit[q]
    elif r['T'] is not None and abs(r['T'] - setpoint[r['cond']]) > 1.0:
        excluded[q] = 'block temp %.1f vs %.1f (sec 2.4)' % (r['T'], setpoint[r['cond']])
for q in sorted(excluded):
    print('EXCL', q, nb[q]['cond'], nb[q]['src'], excluded[q], file=sys.stderr)

kept = {}
for q, r in nb.items():
    if q not in excluded:
        kept.setdefault(r['cond'], []).append((q, r['S'], r['v']))

def fit(pts, V=None):
    S = [p[1] for p in pts]; v = [p[2] for p in pts]
    p = [V if V is not None else max(v), median(S)]
    def sse(p):
        return sum((vi - p[0] * si / (p[1] + si)) ** 2 for si, vi in zip(S, v))
    lam = 1e-3
    cur = sse(p)
    for _ in range(20000):
        Vv, K = p
        r = [vi - Vv * si / (K + si) for si, vi in zip(S, v)]
        J = [(si / (K + si), -Vv * si / (K + si) ** 2) for si in S]
        a11 = sum(j[0] * j[0] for j in J); a12 = sum(j[0] * j[1] for j in J); a22 = sum(j[1] * j[1] for j in J)
        g1 = sum(j[0] * ri for j, ri in zip(J, r)); g2 = sum(j[1] * ri for j, ri in zip(J, r))
