            A11, A22 = a11 * (1 + lam), a22 * (1 + lam)
            det = A11 * A22 - a12 * a12
            dV = (A22 * g1 - a12 * g2) / det
            dK = (A11 * g2 - a12 * g1) / det
            new = [Vv + dV, K + dK]
        else:
            dK = g2 / (a22 * (1 + lam))
            new = [V, K + dK]
        if new[1] <= 0 or new[0] <= 0:
            lam *= 10; continue
        s_new = sse(new)
        if s_new < cur:
            improve = cur - s_new
            p, cur = new, s_new
            lam = max(lam / 3, 1e-12)
            if improve < 1e-16:
                break
        else:
            lam *= 10
            if lam > 1e12:
                break
    return p, cur

result = {}
